<?php
declare(strict_types=1);

/**
 * install_standings_timeline_lite_v004.php
 *
 * VERSION: v001
 * LAST MODIFIED: 8/28/2026 1:40:58 am
 *
 * PURPOSE:
 * Finish the visual-match pass for standings_timeline_lite.php so its four-table
 * report presentation matches weekly_standings.php as closely and literally as possible.
 *
 * VISUAL COMPARISON BASIS:
 * - Same 1920x928 screenshots were compared.
 * - Horizontal table geometry already matched exactly.
 * - Table row pitch already matched exactly at 28px.
 * - Timeline Lite report was 27px lower; this installer corrects that offset.
 * - Table 4 was missing Weekly Standings segment colors; they are added exactly.
 *
 * SAFETY:
 * - exact SHA-256 baseline check for standings_timeline_lite.php v003
 * - backup before replacement
 * - complete-file replacement only
 * - verifies standings_timeline.php dependency is present and remains untouched
 * - rollback on write/postflight failure
 * - no weekly_standings.php change in this pass
 * - no DB, snapshot, scoring, LP/RD, audit, release-history, or timeline-engine changes
 */

date_default_timezone_set('America/New_York');

const LITE_BASE_SHA256 = 'f098222464c933f7e94d5540b4d75f8755defe919ccab777c04b6eded326752e';
const LITE_NEW_SHA256 = 'ff1e82a7921e1efb7c06d3f0bc0892127fefa76a97c0adbbd45b55e966b35084';
const TIMELINE_REFERENCE_SHA256 = 'b3671fae0998576b36055b05e747129a392e173e82b9048a73d05dec4b0b4a2e';

$litePath = __DIR__ . '/standings_timeline_lite.php';
$timelinePath = __DIR__ . '/standings_timeline.php';
$replacement = base64_decode('', true);

function ih(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function row(string $label, bool $ok, string $detail=''): void {
    echo '<tr><td>'.ih($label).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.ih($detail).'</td></tr>';
}
function atomic_write(string $path, string $data): bool {
    $tmp=$path.'.tmp_'.bin2hex(random_bytes(4));
    if(file_put_contents($tmp,$data,LOCK_EX)===false) return false;
    if(!@rename($tmp,$path)) { @unlink($tmp); return false; }
    return true;
}

$liteExists=is_file($litePath);
$timelineExists=is_file($timelinePath);
$currentHash=$liteExists ? (string)hash_file('sha256',$litePath) : '';
$timelineBefore=$timelineExists ? (string)hash_file('sha256',$timelinePath) : '';

$baselineOk=
    $liteExists
    && $currentHash===LITE_BASE_SHA256
    && strpos((string)file_get_contents($litePath),'VERSION: v003')!==false;

$timelineOk=
    $timelineExists
    && strpos((string)file_get_contents($timelinePath),'standings_timeline.php')!==false;

$replacementOk=
    is_string($replacement)
    && hash('sha256',$replacement)===LITE_NEW_SHA256
    && strpos($replacement,'VERSION: v004')!==false
    && strpos($replacement,'margin-bottom: 37px;')!==false
    && strpos($replacement,'weekly-winner-segment-S1')!==false
    && strpos($replacement,'weekly-winner-segment-S2')!==false
    && strpos($replacement,'weekly-winner-segment-S3')!==false
    && strpos($replacement,'weekly-winner-segment-S4')!==false
    && strpos($replacement,'width: 42px;')!==false
    && strpos($replacement,'width: 64px;')!==false
    && strpos($replacement,'AUTO-SCORING – UNOFFICIAL')!==false;

$preflightOk=$baselineOk && $timelineOk && $replacementOk;
$apply=isset($_POST['apply']) && $_POST['apply']==='1';
$messages=[];$success=false;

if($apply && $preflightOk) {
    $backupDir=__DIR__.'/_migration_backups/standings_timeline_lite_v004_'.date('Ymd_His');
    $ok=is_dir($backupDir) || mkdir($backupDir,0755,true);

    if(!$ok) $messages[]='FAIL: Could not create backup directory.';

    if($ok && !copy($litePath,$backupDir.'/standings_timeline_lite.php')) {
        $ok=false;$messages[]='FAIL: Could not back up standings_timeline_lite.php v003.';
    } elseif($ok) {
        $messages[]='PASS: Backed up standings_timeline_lite.php v003.';
    }

    if($ok && !atomic_write($litePath,$replacement)) {
        $ok=false;$messages[]='FAIL: Could not install standings_timeline_lite.php v004.';
    } elseif($ok) {
        $messages[]='PASS: Installed standings_timeline_lite.php v004.';
    }

    if($ok) {
        $installed=(string)file_get_contents($litePath);
        $timelineAfter=is_file($timelinePath) ? (string)hash_file('sha256',$timelinePath) : '';
        $checks=[
            'v004 header'=>strpos($installed,'VERSION: v004')!==false,
            '27px vertical correction'=>strpos($installed,'margin-bottom: 37px;')!==false,
            '1400px report wrapper'=>strpos($installed,'max-width: 1400px;')!==false,
            'four equal report columns'=>strpos($installed,'grid-template-columns: repeat(4, minmax(0, 1fr));')!==false,
            '10px report gaps'=>strpos($installed,'gap: 10px;')!==false,
            '42px rank/week column'=>strpos($installed,'width: 42px;')!==false,
            '64px score column'=>strpos($installed,'width: 64px;')!==false,
            'S1 winner color'=>strpos($installed,'#c5d9f1')!==false,
            'S2 winner color'=>strpos($installed,'#c4bd97')!==false,
            'S3 winner color'=>strpos($installed,'#fcd5b4')!==false,
            'S4 winner color'=>strpos($installed,'#c4d79b')!==false,
            'tie-rank presentation'=>strpos($installed,'class="tie-rank"')!==false,
            'subdued as-of pill retained'=>strpos($installed,"\$topBannerText = 'Standings as of '")!==false,
            'unofficial pill retained'=>strpos($installed,'AUTO-SCORING – UNOFFICIAL')!==false,
            'replacement hash exact'=>hash_file('sha256',$litePath)===LITE_NEW_SHA256,
            'standings_timeline.php untouched'=>$timelineBefore!=='' && $timelineAfter===$timelineBefore,
        ];
        foreach($checks as $label=>$pass) {
            $messages[]=($pass?'PASS: ':'FAIL: ').$label;
            if(!$pass) $ok=false;
        }
    }

    if(!$ok && is_file($backupDir.'/standings_timeline_lite.php')) {
        if(copy($backupDir.'/standings_timeline_lite.php',$litePath)) $messages[]='ROLLBACK: Restored standings_timeline_lite.php v003.';
        else $messages[]='ROLLBACK ERROR: Could not restore standings_timeline_lite.php v003.';
    } else {
        $success=true;
    }
}
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
